package ai.eva.android.probe;
import android.os.*;import java.io.*;import java.util.concurrent.*;import org.json.*;
/** Instantiated by Shizuku as shell/root, never as an exported Android service. */
public class PhoneShellService extends Binder {
 static final String TOKEN="ai.eva.phone.shell.v1";volatile java.lang.Process active;volatile int processGroup;
 public PhoneShellService(){}
 void cancel(){java.lang.Process p=active;if(p!=null){int group=processGroup;if(group>0)try{new ProcessBuilder("/system/bin/kill","-KILL","--","-"+group).start().waitFor(2,TimeUnit.SECONDS);}catch(Exception ignored){}p.destroy();p.destroyForcibly();}}
 protected boolean onTransact(int code,Parcel data,Parcel reply,int flags)throws RemoteException{if(code==16777115){cancel();System.exit(0);return true;}if(code==INTERFACE_TRANSACTION){reply.writeString(TOKEN);return true;}data.enforceInterface(TOKEN);if(code==2){cancel();reply.writeNoException();return true;}if(code!=1)return super.onTransact(code,data,reply,flags);String command=data.readString();JSONObject result=new JSONObject();boolean owned=false;try{if(command==null||command.length()>16000)throw new IOException("命令过长");synchronized(this){if(active!=null)throw new IOException("已有命令正在执行");owned=true;active=new ProcessBuilder("/system/bin/setsid","/system/bin/sh","-c","echo $$; exec /system/bin/sh -c \"$1\"","eva-shell",command).redirectErrorStream(true).start();}java.lang.Process p=active;ByteArrayOutputStream output=new ByteArrayOutputStream();Thread reader=new Thread(()->{try(InputStream stream=p.getInputStream()){ByteArrayOutputStream pid=new ByteArrayOutputStream();int first;while((first=stream.read())!=-1&&first!=10&&pid.size()<20)pid.write(first);processGroup=Integer.parseInt(pid.toString("UTF-8").trim());byte[] buffer=new byte[4096];int n;while((n=stream.read(buffer))!=-1){synchronized(output){int remaining=65536-output.size();if(remaining>0)output.write(buffer,0,Math.min(n,remaining));}}}catch(Exception ignored){}});reader.start();boolean done=p.waitFor(20,TimeUnit.SECONDS);if(!done)cancel();reader.join(1000);synchronized(output){result.put("output",output.toString("UTF-8")).put("truncated",output.size()>=65536);}result.put("uid",android.os.Process.myUid()).put("timedOut",!done);if(done)result.put("exitCode",p.exitValue());}catch(Exception e){try{result.put("error",e.getMessage());}catch(Exception ignored){}}finally{if(owned){cancel();active=null;processGroup=0;}}reply.writeNoException();reply.writeString(result.toString());return true;}
}
